def transform(grid):
    h,w=len(grid),len(grid[0])
    # Markers paired on opposite borders define full horizontal/vertical beams.
    rows={r for r in range(h) if grid[r][0]==1 and grid[r][w-1]==1}
    cols={c for c in range(w) if grid[0][c]==1 and grid[h-1][c]==1}
    out=[row[:] for row in grid]
    for r in rows:
        out[r]=[1]*w
    for c in cols:
        for r in range(h):
            out[r][c]=1
    # Any 2-object intersected by a beam is recolored entirely.
    visited=set()
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=2 or (r,c) in visited:
                continue
            stack=[(r,c)]; visited.add((r,c)); comp=[]
            while stack:
                x,y=stack.pop(); comp.append((x,y))
                for a,b in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
                    if 0<=a<h and 0<=b<w and grid[a][b]==2 and (a,b) not in visited:
                        visited.add((a,b)); stack.append((a,b))
            if any((x,y) in {(rr,cc) for rr in rows for cc in range(w)} | {(rr,cc) for cc in cols for rr in range(h)} for x,y in comp):
                for x,y in comp: out[x][y]=1
    return out
